#include <vector>

// hidden test helper: 1 or 0 for each add, then size() and span()
std::vector<long long> run_log(const std::vector<long long>& times) {
    TickLog g;
    std::vector<long long> out;
    for (long long t : times) out.push_back(g.add(t) ? 1 : 0);
    out.push_back(g.size());
    out.push_back(g.span());
    return out;
}

